const TITLE = "Averages — Sign In";
const STYLE_CSS = "\n\n  :root {\n    /* Accent color system — swap this one value to re-theme the whole app */\n    --accent: #3d3f9e;\n    --accent-dark: #1a1c66;\n    --accent-darker: #0d0e33;\n    /* Derived from --accent so the focus ring re-themes automatically\n       whenever --accent changes (no need to hand-update this value). */\n    --accent-ring: rgb(from var(--accent) r g b / 0.35);\n    --card-bg: #f2f2f4;\n    --text-dark: #14151f;\n    --text-muted: #4b4d63;\n    --button-text: #ffffff;\n    --radius-lg: 20px;\n    --radius-md: 12px;\n  }\n\n  * { box-sizing: border-box; }\n\n  /* Scrollbars app-wide: a slim, permanently-visible, rounded gray bar\n     sitting slightly inset from the true edge of its scrollable area --\n     like a normal OS/Gmail-style scrollbar, not hidden and not\n     hover-gated. (An earlier hover-only version turned out unreliable:\n     the outer page counts as \"hovered\" almost the entire time you're\n     using it, so it either showed constantly or never, depending on the\n     browser -- not the meaningful hover signal it needed to be.)\n     Scrolling itself always works via wheel/trackpad/touch/keys either\n     way. One universal rule (the `*` selector) so it covers every\n     scrollable element automatically — the outer page scroll, every\n     popup/modal, every internal list — without repeating it per\n     element. (The bottom nav's own horizontal scroll strip is a\n     deliberate exception — see .app-nav-inner further down — that one\n     stays permanently hidden as a mobile overflow safety net.) */\n  * {\n    scrollbar-width: thin;\n    scrollbar-color: rgba(20, 21, 31, 0.28) transparent;\n  }\n  *::-webkit-scrollbar { width: 10px; height: 10px; }\n  *::-webkit-scrollbar-track { background: transparent; }\n  *::-webkit-scrollbar-thumb {\n    background-color: rgba(20, 21, 31, 0.28);\n    border-radius: 999px;\n    border: 2px solid transparent;\n    background-clip: padding-box; /* the transparent border creates the\n      inset gap around the thumb, so it reads as sitting inside the\n      window rather than flush against the very edge */\n  }\n  *::-webkit-scrollbar-thumb:hover { background-color: rgba(20, 21, 31, 0.45); }\n  *::-webkit-scrollbar-corner { background: transparent; }\n\n  html, body {\n    margin: 0;\n    padding: 0;\n    height: 100%;\n    font-family: \"puffin\", -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif;\n  }\n\n  body {\n    height: 100vh; /* fixed, not min -- body itself no longer scrolls */\n    overflow: hidden; /* scrolling now happens inside .scroll-frame (see\n      below, wrapping .page), so the scrollbar sits at the edge of the\n      app's own window instead of out at the browser's outer edge, over\n      the wallpaper margin */\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    padding: 24px;\n    /* Gradient rebuilt from color stops sampled straight down Martin's\n       Illustrator export, rather than a tiny raster crop stretched to\n       cover (which blew up into a zoomed/blurry look at full-page size).\n       background-color is the fallback before the gradient paints. */\n    background-image: linear-gradient(180deg, #1e5b96 0%, #004298 16.7%, #001e92 33.3%, #001498 50%, #0015a2 66.7%, #0016ad 83.3%, #1c2aaa 100%);\n    background-size: cover;\n    background-position: center;\n    background-repeat: no-repeat;\n    background-color: var(--accent-dark);\n  }\n\n  /* Wraps .page and is the actual scroll container: width-matched to\n     .page's own max-width so its scrollbar sits at the edge of the login\n     window itself, not out at the browser's edge over the wallpaper.\n     align-self:stretch overrides body's align-items:center just for this\n     element, giving it a real bounded height to scroll within. Centering\n     .page inside it uses margin:auto on .page itself (below), not\n     justify-content:center here -- a centered flex container's scrollHeight\n     doesn't reliably account for content that overflows past the centered\n     position (verified: it under-reports how far there is to scroll, so\n     part of the content becomes unreachable), while auto margins don't\n     have that bug and degrade to plain top alignment once content no\n     longer fits. */\n  .scroll-frame {\n    width: 100%;\n    max-width: 1100px;\n    align-self: stretch;\n    min-height: 0;\n    overflow-y: auto;\n    overflow-x: hidden;\n    display: flex;\n    flex-direction: column;\n  }\n\n  .page {\n    width: 100%;\n    margin: auto 0; /* vertically centers .page within .scroll-frame when\n      it fits; collapses to 0 (top-aligned, fully scrollable) once it\n      doesn't -- see the comment on .scroll-frame above */\n    display: flex;\n    align-items: flex-start;\n    justify-content: space-between;\n    gap: 48px;\n    flex-wrap: wrap;\n  }\n\n  .card {\n    background: var(--card-bg);\n    border-radius: var(--radius-lg);\n    padding: 32px;\n    max-width: 460px;\n  }\n\n  .card h2 {\n    margin: 0 0 18px 0;\n    font-size: 1.5rem;\n    font-weight: 800;\n    color: var(--text-dark);\n  }\n\n  .btn {\n    width: 100%;\n    display: block;\n    text-align: center;\n    padding: 16px 20px;\n    border-radius: var(--radius-md);\n    border: none;\n    font-size: 1rem;\n    font-weight: 700;\n    color: var(--button-text);\n    background: var(--accent-dark);\n    cursor: pointer;\n    margin-bottom: 14px;\n    transition: transform 0.08s ease, filter 0.15s ease;\n    font-family: inherit;\n  }\n\n  .btn:last-of-type { margin-bottom: 0; }\n\n  .btn:hover { filter: brightness(1.12); }\n  .btn:active { transform: scale(0.99); }\n\n  .btn.secondary {\n    background: var(--accent-dark);\n    position: relative;\n  }\n\n  .btn[disabled] {\n    cursor: not-allowed;\n    opacity: 0.55;\n    filter: none;\n  }\n  .btn[disabled]:hover { filter: none; }\n\n  .badge {\n    display: inline-block;\n    font-size: 0.65rem;\n    font-weight: 800;\n    text-transform: uppercase;\n    letter-spacing: 0.04em;\n    background: rgba(255, 255, 255, 0.18);\n    padding: 2px 8px;\n    border-radius: 999px;\n    margin-left: 8px;\n    vertical-align: middle;\n  }\n\n  /* Expanding API-key form */\n  .key-form {\n    max-height: 0;\n    overflow: hidden;\n    transition: max-height 0.25s ease;\n    /* Padding + matching negative margin: gives the focus ring on the\n       inputs inside room to render without being clipped by this\n       container's overflow:hidden, while keeping everything lined up\n       with the buttons above/below (which sit flush with the card edge). */\n    margin: 0 -6px;\n    padding: 0 6px;\n  }\n  .key-form.open { max-height: 340px; }\n\n  .key-form-inner {\n    padding-top: 8px;\n    padding-bottom: 14px;\n  }\n\n  .field {\n    margin-bottom: 12px;\n  }\n\n  .field label {\n    display: block;\n    font-size: 0.75rem;\n    font-weight: 700;\n    color: var(--text-muted);\n    margin-bottom: 6px;\n  }\n\n  .field input[type=\"text\"],\n  .field input[type=\"password\"] {\n    width: 100%;\n    padding: 12px 14px;\n    border-radius: var(--radius-md);\n    border: 1px solid #d3d3da;\n    font-size: 0.9rem;\n    font-family: inherit;\n    background: #ffffff;\n    color: var(--text-dark);\n  }\n\n  .field input:focus {\n    outline: none;\n    border-color: var(--accent);\n    box-shadow: 0 0 0 3px var(--accent-ring);\n  }\n\n  .tooltip-wrap {\n    position: relative;\n    display: inline-flex;\n    align-items: center;\n    margin-top: -4px;\n    margin-bottom: 12px;\n  }\n\n  .helper-link {\n    font-size: 0.72rem;\n    color: var(--text-muted);\n    text-decoration: underline;\n    display: inline-block;\n  }\n\n  .info-icon {\n    display: inline-flex;\n    align-items: center;\n    justify-content: center;\n    width: 14px;\n    height: 14px;\n    vertical-align: middle;\n    margin-left: 2px;\n    cursor: default;\n    color: var(--text-muted);\n  }\n\n  .info-icon svg {\n    width: 100%;\n    height: 100%;\n    display: block;\n  }\n\n  .tooltip-bubble {\n    position: absolute;\n    bottom: calc(100% + 10px);\n    left: 50%;\n    transform: translateX(-50%) translateY(4px);\n    background: var(--accent-dark);\n    color: #ffffff;\n    font-size: 0.7rem;\n    font-weight: 600;\n    line-height: 1.35;\n    padding: 8px 10px;\n    border-radius: 8px;\n    width: max-content;\n    max-width: 220px;\n    text-align: center;\n    box-shadow: 0 10px 24px -8px rgba(0, 0, 0, 0.45);\n    opacity: 0;\n    visibility: hidden;\n    pointer-events: none;\n    transition: opacity 0.15s ease, transform 0.15s ease;\n    z-index: 5;\n  }\n\n  .tooltip-bubble::after {\n    content: \"\";\n    position: absolute;\n    top: 100%;\n    left: 50%;\n    transform: translateX(-50%);\n    border: 6px solid transparent;\n    border-top-color: var(--accent-dark);\n  }\n\n  .tooltip-wrap:hover .tooltip-bubble,\n  .tooltip-wrap:focus-within .tooltip-bubble {\n    opacity: 1;\n    visibility: visible;\n    transform: translateX(-50%) translateY(0);\n  }\n\n  .connect-btn {\n    background: var(--accent);\n    position: relative;\n  }\n\n  /* Connect button loading/error states — the label crossfades out and either\n     three pulsing dots (checking the credentials) or an X (failed) crossfades\n     in over the same spot, so the button never changes size mid-animation. */\n  .connect-btn .btn-label {\n    display: inline-block;\n    transition: opacity 0.18s ease;\n  }\n\n  .connect-btn .btn-dots,\n  .connect-btn .btn-x {\n    position: absolute;\n    top: 50%;\n    left: 50%;\n    transform: translate(-50%, -50%);\n    opacity: 0;\n    pointer-events: none;\n    transition: opacity 0.18s ease;\n  }\n\n  .connect-btn.loading .btn-label,\n  .connect-btn.error .btn-label {\n    opacity: 0;\n  }\n\n  .connect-btn.loading .btn-dots { opacity: 1; }\n  .connect-btn.error .btn-x { opacity: 1; }\n\n  .connect-btn .btn-dots span {\n    display: inline-block;\n    width: 7px;\n    height: 7px;\n    margin: 0 3px;\n    border-radius: 50%;\n    background: currentColor;\n    opacity: 0.35;\n    animation: connectDotPulse 1.1s ease-in-out infinite;\n  }\n  .connect-btn .btn-dots span:nth-child(2) { animation-delay: 0.15s; }\n  .connect-btn .btn-dots span:nth-child(3) { animation-delay: 0.3s; }\n\n  @keyframes connectDotPulse {\n    0%, 80%, 100% { opacity: 0.35; transform: scale(0.85); }\n    40% { opacity: 1; transform: scale(1); }\n  }\n\n  .connect-btn .btn-x svg {\n    width: 18px;\n    height: 18px;\n    display: block;\n  }\n\n  /* Error is its own background rather than just an icon swap, so a failed\n     attempt reads clearly even to someone not looking right at the button. */\n  .connect-btn.error { background: #b3261e; }\n\n  /* The button is legitimately disabled (not just busy) while these states\n     show, but the generic .btn[disabled] dimming would wash out the dots/X —\n     override it back to full opacity for just these two states. */\n  .connect-btn.loading[disabled],\n  .connect-btn.error[disabled] {\n    opacity: 1;\n    filter: none;\n    cursor: not-allowed;\n  }\n\n  @media (prefers-reduced-motion: reduce) {\n    .connect-btn .btn-dots span {\n      animation: none;\n      opacity: 0.7;\n    }\n  }\n\n  .tooltip {\n    display: none;\n    font-size: 0.72rem;\n    color: var(--text-muted);\n    margin-top: -8px;\n    margin-bottom: 14px;\n    font-weight: 600;\n  }\n  .tooltip.show { display: block; }\n\n\n  /* ---------- Sign-in by LMS (draft, 2026-10-06, from Martin's \"Select your\n     LMS\" mock): one card with a grey title band, three screens inside it.\n     1. Select your platform: Schoology, Canvas, Google Classroom (read only).\n     2. Schoology / Canvas: search your school on the left, the picked school\n        on the right with the 13+ check and Log in with Schoology / Canvas.\n        Not every school uses SSO: the button sends the student to their\n        school's own Schoology or Canvas sign-in page, which shows whatever\n        that school uses (its SSO, or a Schoology/Canvas password). The\n        password is never typed into Averages.io.\n     3. Google Classroom: the 13+ check and Continue with Google.\n     Screens are hash routes (#schoology, #canvas, #google) so the browser's\n     Back button walks back through them. ---------- */\n  :root {\n    --band-bg: #76777c;\n    --band-text: #0d0e14;\n    --sheet-bg: #c9d0da;\n    --sheet-text: #14151f;\n    --sheet-muted: #3a4260;\n    --lms-schoology: #0a1d9e;\n    --lms-canvas: #1e1d66;\n    --lms-classroom: #0619a8;\n    --sso-bg: #0a1d9e;\n  }\n  .page { justify-content: center; align-items: center; flex-direction: column; gap: 14px; }\n  .lms-card {\n    width: 100%;\n    max-width: 780px;\n    border-radius: 36px;\n    overflow: hidden;\n    background: var(--sheet-bg);\n    box-shadow: 0 34px 60px -34px rgba(0, 0, 20, 0.85);\n  }\n  .screen[hidden] { display: none; }\n  .screen { animation: screenIn 0.22s ease both; }\n  @keyframes screenIn { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }\n  @media (prefers-reduced-motion: reduce) { .screen { animation: none; } }\n\n  /* Title band */\n  .lms-band {\n    background: var(--band-bg);\n    color: var(--band-text);\n    padding: 22px 44px 18px;\n    min-height: 92px;\n    display: flex;\n    flex-direction: column;\n    justify-content: flex-end;\n    gap: 6px;\n  }\n  .lms-logo { width: 36px; height: 36px; display: block; margin-left: 2px; }\n  .lms-title { margin: 0; font-size: 1.05rem; font-weight: 800; letter-spacing: -0.01em; outline: none; }\n  .lms-band.big .lms-title { font-size: 1.85rem; letter-spacing: -0.02em; }\n  .lms-back {\n    align-self: flex-start;\n    display: inline-flex;\n    align-items: center;\n    gap: 6px;\n    margin: 0 0 2px -6px;\n    padding: 4px 8px 4px 4px;\n    border: 0;\n    border-radius: 999px;\n    background: transparent;\n    color: var(--band-text);\n    font: inherit;\n    font-size: 0.95rem;\n    font-weight: 700;\n    cursor: pointer;\n  }\n  .lms-back svg { width: 20px; height: 20px; display: block; }\n  .lms-back:hover { background: rgba(255, 255, 255, 0.14); }\n  .lms-back:focus-visible { outline: none; box-shadow: 0 0 0 3px rgba(255, 255, 255, 0.55); }\n\n  /* Body sheet */\n  .lms-sheet { padding: 28px 36px 34px; color: var(--sheet-text); min-height: 260px; }\n  .lms-prompt { margin: 6px 0 22px; text-align: center; font-size: 1.05rem; font-weight: 800; }\n  .lms-choices { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; }\n  .lms-btn {\n    min-height: 54px;\n    padding: 8px 18px;\n    border: 0;\n    border-radius: 999px;\n    color: #ffffff;\n    font: inherit;\n    font-size: 1.05rem;\n    font-weight: 800;\n    line-height: 1.1;\n    cursor: pointer;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    justify-content: center;\n    transition: filter 0.15s ease, transform 0.08s ease;\n  }\n  .lms-btn small { font-size: 0.7rem; font-weight: 700; opacity: 0.92; margin-top: 2px; }\n  .lms-btn:hover { filter: brightness(1.15); }\n  .lms-btn:active { transform: scale(0.985); }\n  .lms-btn:focus-visible, .lms-sso:focus-visible { outline: none; box-shadow: 0 0 0 3px #ffffff, 0 0 0 6px var(--lms-schoology); }\n  .lms-btn[data-lms=\"schoology\"] { background: var(--lms-schoology); }\n  .lms-btn[data-lms=\"canvas\"] { background: var(--lms-canvas); }\n  .lms-btn[data-lms=\"google\"] { background: var(--lms-classroom); }\n  .lms-legal { margin: 22px 8px 0; font-size: 0.92rem; font-weight: 700; color: var(--sheet-muted); }\n  .lms-legal a, .lms-missing a { color: #0b2fb8; font-weight: 800; text-decoration: underline; text-underline-offset: 2px; }\n\n  /* School screens: search left, picked school right */\n  .school-grid { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 0.82fr); gap: 28px; align-items: start; }\n  .school-search { position: relative; }\n  .school-input {\n    width: 100%;\n    height: 50px;\n    padding: 0 18px;\n    border: 0;\n    border-radius: 999px;\n    background: #ffffff;\n    color: var(--sheet-text);\n    font: inherit;\n    font-size: 1rem;\n    font-weight: 700;\n  }\n  .school-input::placeholder { color: #14151f; opacity: 0.9; }\n  .school-input:focus { outline: none; box-shadow: 0 0 0 3px var(--accent-ring); }\n  .school-input::-webkit-search-cancel-button { cursor: pointer; }\n  .school-results { list-style: none; margin: 10px 0 0; padding: 0; display: flex; flex-direction: column; gap: 6px; max-height: 236px; overflow-y: auto; }\n  .school-results:empty { display: none; }\n  .school-option {\n    display: flex;\n    flex-direction: column;\n    gap: 2px;\n    padding: 10px 16px;\n    border-radius: 16px;\n    background: rgba(255, 255, 255, 0.55);\n    cursor: pointer;\n  }\n  .school-option:hover, .school-option.active { background: #ffffff; }\n  /* Picked = white with a check (selection is a tint plus a mark, never a colored border). */\n  .school-option { position: relative; padding-right: 44px; }\n  .school-option[aria-selected=\"true\"] { background: #ffffff; }\n  .school-option[aria-selected=\"true\"]::after { content: \"\"; position: absolute; right: 18px; top: 50%; width: 12px; height: 7px; border: solid var(--sso-bg); border-width: 0 0 3px 3px; transform: translateY(-70%) rotate(-45deg); }\n  .school-option .o-name { font-weight: 800; font-size: 0.95rem; }\n  .school-option mark { background: rgba(10, 29, 158, 0.13); color: inherit; border-radius: 4px; padding: 0 1px; }\n  .school-option .o-domain { font-weight: 600; font-size: 0.82rem; color: var(--sheet-muted); }\n  .school-hint { margin: 12px 4px 0; font-size: 0.86rem; font-weight: 600; color: var(--sheet-muted); line-height: 1.45; }\n  .school-hint:empty { display: none; }\n  .school-hint button { border: 0; background: none; padding: 0; font: inherit; color: #0b2fb8; font-weight: 800; text-decoration: underline; text-underline-offset: 2px; cursor: pointer; }\n  .age-row { display: flex; align-items: center; justify-content: center; gap: 10px; flex-wrap: wrap; }\n  .age-why { border: 0; background: rgba(255, 255, 255, 0.55); color: var(--sheet-text); font: inherit; font-size: 0.78rem; font-weight: 800; padding: 4px 10px; border-radius: 999px; cursor: pointer; }\n  .age-why:hover { background: #ffffff; }\n  .age-why:focus-visible { outline: none; box-shadow: 0 0 0 3px var(--accent-ring); }\n  .age-note { margin: 0; max-width: 320px; font-size: 0.82rem; font-weight: 600; color: var(--sheet-muted); line-height: 1.45; }\n  .age-note[hidden] { display: none; }\n\n  .school-pick { text-align: center; padding-top: 18px; display: flex; flex-direction: column; align-items: center; gap: 10px; }\n  .pick-name { margin: 0; font-size: 1rem; font-weight: 700; color: var(--sheet-muted); }\n  .pick-domain { margin: 0; font-size: 1.15rem; font-weight: 800; color: var(--sheet-text); word-break: break-all; }\n  .school-pick.empty .pick-domain { font-size: 0.92rem; font-weight: 600; color: var(--sheet-muted); }\n  .age-check { display: inline-flex; align-items: center; gap: 12px; margin: 6px 0 4px; font-size: 1rem; font-weight: 700; color: var(--sheet-text); cursor: pointer; user-select: none; }\n  .age-check input { appearance: none; -webkit-appearance: none; flex: none; width: 26px; height: 26px; margin: 0; border-radius: 50%; border: 2px solid #8b92a8; background: #ffffff; cursor: pointer; display: grid; place-items: center; transition: background-color 0.15s ease, border-color 0.15s ease; }\n  .age-check input:checked { background: var(--sso-bg); border-color: var(--sso-bg); }\n  .age-check input:focus-visible { outline: none; box-shadow: 0 0 0 3px var(--accent-ring); }\n  .lms-sso {\n    width: 100%;\n    max-width: 300px;\n    min-height: 50px;\n    padding: 10px 22px;\n    border: 0;\n    border-radius: 999px;\n    background: var(--sso-bg);\n    color: #ffffff;\n    font: inherit;\n    font-size: 1.1rem;\n    font-weight: 800;\n    cursor: pointer;\n    transition: filter 0.15s ease, opacity 0.15s ease;\n  }\n  .lms-sso:hover:not([disabled]) { filter: brightness(1.15); }\n  .lms-sso[disabled] { opacity: 0.45; cursor: not-allowed; }\n  .lms-sso.busy { pointer-events: none; opacity: 0.8; }\n  .lms-sso.google { background: #ffffff; color: #1f1f1f; box-shadow: inset 0 0 0 1px #b9bdc9; }\n  .lms-sso.google:hover { filter: none; background: #f4f5f8; }\n  .signin-note { margin: 4px 0 0; padding: 10px 14px; border-radius: 14px; background: rgba(255, 255, 255, 0.6); color: var(--sheet-text); font-size: 0.86rem; font-weight: 700; line-height: 1.4; max-width: 320px; }\n  .signin-note[hidden] { display: none; }\n  .lms-missing { margin: 30px 8px 0; text-align: center; font-size: 0.95rem; font-weight: 700; color: var(--sheet-text); line-height: 1.5; }\n  .lms-missing[hidden] { display: none; }\n  .lms-missing button { border: 0; background: none; padding: 0; font: inherit; color: #0b2fb8; font-weight: 800; text-decoration: underline; text-underline-offset: 2px; cursor: pointer; }\n\n  /* Google Classroom screen */\n  .google-pane { max-width: 420px; margin: 0 auto; text-align: center; display: flex; flex-direction: column; align-items: center; gap: 12px; padding-top: 6px; }\n  .google-pane p { margin: 0; font-size: 0.95rem; font-weight: 600; color: var(--sheet-muted); line-height: 1.5; }\n  .google-pane .ro { font-weight: 800; color: var(--sheet-text); }\n\n  /* Email Template sheet (Canvas) */\n  .tpl-overlay { position: fixed; inset: 0; background: rgba(5, 8, 40, 0.55); display: grid; place-items: center; padding: 20px; z-index: 50; }\n  .tpl-overlay[hidden] { display: none; }\n  .tpl-modal { width: 100%; max-width: 520px; background: #f2f2f4; border-radius: 24px; padding: 24px; box-shadow: 0 30px 70px -30px rgba(0, 0, 0, 0.6); }\n  .tpl-modal h2 { margin: 0 0 6px; font-size: 1.2rem; font-weight: 800; color: var(--text-dark); }\n  .tpl-modal p { margin: 0 0 12px; font-size: 0.88rem; font-weight: 600; color: var(--text-muted); line-height: 1.45; }\n  .tpl-text { width: 100%; min-height: 220px; padding: 12px 14px; border-radius: 14px; border: 1px solid #d3d3da; background: #ffffff; font: inherit; font-size: 0.88rem; line-height: 1.5; color: var(--text-dark); resize: vertical; }\n  .tpl-text:focus { outline: none; border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-ring); }\n  .tpl-actions { display: flex; gap: 10px; justify-content: flex-end; margin-top: 14px; flex-wrap: wrap; }\n  .tpl-actions button, .tpl-actions a { min-height: 42px; padding: 0 18px; border-radius: 999px; border: 0; font: inherit; font-size: 0.92rem; font-weight: 800; cursor: pointer; display: inline-flex; align-items: center; text-decoration: none; }\n  .tpl-close { background: #e2e3ea; color: var(--text-dark); }\n  .tpl-copy, .tpl-mail { background: var(--sso-bg); color: #ffffff; }\n\n  .sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }\n  .signin-foot { margin: 0; font-size: 0.78rem; font-weight: 700; color: rgba(255,255,255,0.82); text-align: center; }\n  .signin-foot a { color: inherit; font-weight: 800; text-decoration: underline; text-underline-offset: 2px; }\n  .dev-keys { margin-top: 26px; padding-top: 18px; border-top: 1px solid rgba(20,21,31,0.14); max-width: 420px; margin-left: auto; margin-right: auto; }\n  .dev-keys[hidden] { display: none; }\n  .dev-keys-label { margin: 0 0 10px; font-size: 0.7rem; font-weight: 800; letter-spacing: 0.06em; text-transform: uppercase; color: var(--sheet-muted); text-align: center; }\n  .dev-keys .btn { border-radius: 999px; }\n\n  /* Bigger on computers (2026-10-06, per Martin): the card grows with the\n     window up to 1120px wide, and everything inside scales with it. */\n  @media (min-width: 900px) {\n    .scroll-frame { max-width: 1180px; }\n    .lms-card { max-width: min(1120px, 88vw); border-radius: 44px; }\n    .lms-band { padding: 30px 60px 24px; min-height: 128px; gap: 8px; }\n    .lms-logo { width: 48px; height: 48px; }\n    .lms-title { font-size: 1.4rem; }\n    .lms-band.big .lms-title { font-size: 2.5rem; }\n    .lms-back { font-size: 1.15rem; }\n    .lms-back svg { width: 24px; height: 24px; }\n    .lms-sheet { padding: 40px 52px 48px; min-height: 360px; }\n    .lms-prompt { font-size: 1.45rem; margin: 10px 0 32px; }\n    .lms-choices { gap: 16px; }\n    .lms-btn { min-height: 74px; font-size: 1.4rem; }\n    .lms-btn small { font-size: 0.85rem; }\n    .lms-legal { font-size: 1.12rem; margin-top: 30px; }\n    .school-grid { gap: 44px; }\n    .school-input { height: 64px; padding: 0 26px; font-size: 1.2rem; }\n    .school-results { gap: 8px; max-height: 320px; }\n    .school-option { padding: 14px 22px; padding-right: 52px; border-radius: 20px; }\n    .school-option .o-name { font-size: 1.1rem; }\n    .school-option .o-domain { font-size: 0.95rem; }\n    .school-hint { font-size: 1rem; }\n    .school-pick { gap: 14px; padding-top: 22px; }\n    .pick-name { font-size: 1.2rem; }\n    .pick-domain { font-size: 1.4rem; }\n    .school-pick.empty .pick-domain { font-size: 1.05rem; }\n    .age-check { font-size: 1.2rem; gap: 14px; }\n    .age-check input { width: 32px; height: 32px; }\n    .age-why { font-size: 0.9rem; padding: 6px 14px; }\n    .age-note { font-size: 0.95rem; max-width: 400px; }\n    .lms-sso { max-width: 380px; min-height: 64px; font-size: 1.3rem; }\n    .signin-note { font-size: 0.98rem; max-width: 400px; }\n    .lms-missing { font-size: 1.1rem; margin-top: 40px; }\n    .google-pane { max-width: 520px; gap: 16px; }\n    .google-pane p { font-size: 1.1rem; }\n    .signin-foot { font-size: 0.9rem; }\n  }\n  @media (min-width: 1600px) {\n    .scroll-frame { max-width: 1480px; }\n    .lms-card { max-width: min(1400px, 76vw); border-radius: 52px; }\n    .lms-band { padding: 36px 72px 28px; min-height: 150px; }\n    .lms-logo { width: 56px; height: 56px; }\n    .lms-title { font-size: 1.65rem; }\n    .lms-band.big .lms-title { font-size: 3rem; }\n    .lms-back { font-size: 1.3rem; }\n    .lms-sheet { padding: 48px 64px 56px; min-height: 420px; }\n    .lms-prompt { font-size: 1.7rem; margin-bottom: 38px; }\n    .lms-btn { min-height: 86px; font-size: 1.65rem; }\n    .lms-btn small { font-size: 0.95rem; }\n    .lms-legal { font-size: 1.3rem; }\n    .school-input { height: 74px; font-size: 1.4rem; padding: 0 30px; }\n    .school-option .o-name { font-size: 1.25rem; }\n    .school-option .o-domain { font-size: 1.05rem; }\n    .school-hint { font-size: 1.15rem; }\n    .pick-name { font-size: 1.4rem; }\n    .pick-domain { font-size: 1.65rem; }\n    .school-pick.empty .pick-domain { font-size: 1.2rem; }\n    .age-check { font-size: 1.4rem; }\n    .age-check input { width: 36px; height: 36px; }\n    .age-why { font-size: 1rem; }\n    .age-note { font-size: 1.08rem; max-width: 460px; }\n    .lms-sso { max-width: 440px; min-height: 74px; font-size: 1.5rem; }\n    .lms-missing { font-size: 1.28rem; }\n    .google-pane { max-width: 620px; }\n    .google-pane p { font-size: 1.28rem; }\n  }\n  @media (max-width: 680px) {\n    body { padding: 16px; }\n    .lms-card { border-radius: 28px; }\n    .lms-band { padding: 18px 24px 16px; min-height: 0; }\n    .lms-band.big .lms-title { font-size: 1.5rem; }\n    .lms-sheet { padding: 22px 20px 26px; min-height: 0; }\n    .lms-choices { grid-template-columns: 1fr; }\n    .school-grid { grid-template-columns: 1fr; gap: 18px; }\n    .school-pick { padding-top: 4px; }\n    .lms-missing { margin-top: 22px; }\n  }\n";
